import{_ as p,a0 as r,w as u,s as l,ao as a,I as n,x as s,a1 as e,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Ubuntu 中使用和自定義程序塢 | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 中使用和自定義程序塢 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 中使用和自定義程序塢 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 中使用和自定義程序塢 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20210108 The Definitive Guide to Using and Customizing the Dock in Ubuntu","title":"在 Ubuntu 中使用和自定義程序塢","tag":"202211","desc":""},"relativePath":"202211/20210108 The Definitive Guide to Using and Customizing the Dock in Ubuntu.md","filePath":"[post].md"}'),d={name:"202211/20210108 The Definitive Guide to Using and Customizing the Dock in Ubuntu.md"};function b(h,t,m,c,g,k){const i=r("Link");return u(),l("div",null,[t[29]||(t[29]=a('<h1 id="在-ubuntu-中使用和自定義程序塢" tabindex="-1">在 Ubuntu 中使用和自定義程序塢 <a class="header-anchor" href="#在-ubuntu-中使用和自定義程序塢" aria-label="Permalink to “在 Ubuntu 中使用和自定義程序塢”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/23/143533heym0bybbfm0bfbj.jpg" alt=""></p><p>當你登錄 Ubuntu 時，你會看到屏幕左側的 <ruby>程序塢/停靠欄<rt> dock </rt></ruby>，上面有一些應用程序的圖標。程序塢（也稱為 <ruby>啓動器<rt> launcher </rt></ruby>，或者 <ruby>面板<rt> panel </rt></ruby>）可以讓你快速啓動某個常用的應用程序。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/01/ubuntu-dock.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>我經常使用程序塢。在本文中，我將分享一些關於有效使用程序塢的小技巧，並介紹自定義程序塢的外觀和位置的方法。</p><p>你將在本教程中學習到以下內容：</p><ul><li>程序塢的基本用途：添加應用程序，並使用快捷方式來啓動應用程序</li><li>自定義程序塢的外觀：更改圖標大小、圖標位置</li><li>更改程序塢的位置：可用於單屏和多顯示器的設置</li><li>在程序塢中隱藏已安裝的磁盤圖標</li><li>自動隱藏或禁用程序塢</li><li>使用 <code>dconf-editor</code> 對程序塢進行額外的定製</li><li>用其他程序塢應用程序替換 Ubuntu 默認的程序塢</li></ul><p>我將在教程中使用 <ruby>程序塢<rt> dock </rt></ruby>、<ruby>面板<rt> panel </rt></ruby>和 <ruby>啓動器<rt> launcher </rt></ruby> 等術語，它們的意思是等同的。</p><h3 id="如何使用-ubuntu-程序塢-你必須知道的基礎知識" tabindex="-1">如何使用 Ubuntu 程序塢：你必須知道的基礎知識 <a class="header-anchor" href="#如何使用-ubuntu-程序塢-你必須知道的基礎知識" aria-label="Permalink to “如何使用 Ubuntu 程序塢：你必須知道的基礎知識”">​</a></h3><p>如果你是 Ubuntu 的新手，你需要掌握如何使用程序塢。儘管，在一段時間後你總會熟悉程序塢的功能，但是閲讀本文能讓你更快地明白。</p><h4 id="向程序塢添加新的應用程序-或刪除應用程序" tabindex="-1">向程序塢添加新的應用程序（或刪除應用程序） <a class="header-anchor" href="#向程序塢添加新的應用程序-或刪除應用程序" aria-label="Permalink to “向程序塢添加新的應用程序（或刪除應用程序）”">​</a></h4><p>這一步驟十分簡單。從菜單中搜索你想要添加在程序塢的應用程序，然後運行它。</p><p>正在運行的應用程序會顯示在程序塢中，它的圖標在程序塢中所有圖標的下方。右鍵單擊該圖標，然後選擇 “<ruby>添加到收藏夾<rt> Add to Favorites </rt></ruby>” 選項。這會把該應用程序的圖標鎖定到程序塢上。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/01/add-icons-to-dock.png?resize=800%2C450&amp;ssl=1" alt="Right-click on the icon and select “Add to Favorites”"></p><p>從程序塢中刪除應用程序的圖標，操作起來更為簡單。你不需要運行你想要在程序塢刪除的應用程序，只需右鍵單擊應用程序圖標，然後選擇 “<ruby>從收藏夾中刪除<rt> Remove From Favorites </rt></ruby>” 即可。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/01/remove-icons-from-dock.png?resize=800%2C450&amp;ssl=1" alt="Right-click on the icon and select “Remove from Favorites”"></p><h4 id="更改程序塢中的圖標順序" tabindex="-1">更改程序塢中的圖標順序 <a class="header-anchor" href="#更改程序塢中的圖標順序" aria-label="Permalink to “更改程序塢中的圖標順序”">​</a></h4><p>默認情況下，新添加到程序塢的應用程序圖標會放置在程序塢上的所有圖標之後。但是，你也可以改變圖標的位置。</p><p>要更改圖標的順序，你只需將它拖放到另一個位置即可，不用 “<ruby>鎖定位置<rt> lock it </rt></ruby>”，或者做其他的事情。如果你不做任何的更改，這個圖標會一直停留在那個位置。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/01/reorder-icons-on-ubuntu-docks.gif?resize=800%2C430&amp;ssl=1" alt="Reorder Icons On Ubuntu Docks"></p><h4 id="右鍵單擊程序塢中的圖標-以獲取應用程序的額外選項" tabindex="-1">右鍵單擊程序塢中的圖標，以獲取應用程序的額外選項 <a class="header-anchor" href="#右鍵單擊程序塢中的圖標-以獲取應用程序的額外選項" aria-label="Permalink to “右鍵單擊程序塢中的圖標，以獲取應用程序的額外選項”">​</a></h4><p>左鍵單擊程序塢中的圖標會啓動應用程序，或者如果應用程序已經在運行，則這個應用程序會被聚焦，即它會出現在所有其他正在運行的應用程序窗口前面。</p><p>右鍵單擊程序塢中的圖標會為你提供應用程序的額外選項。不同的應用程序會有不同的選項。</p><p>右鍵單擊<strong>瀏覽器</strong>圖標，在它的額外選項中，你可以打開一個新的私人窗口，或預覽所有正在運行的窗口。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/01/right-click-icons-ubuntu-dock.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>右鍵單擊<strong>文件管理器</strong>圖標，在它的額外選項中，你可以查看所有已添加書籤的目錄，或預覽打開的窗口。</p><p>當然，你也可以通過右鍵單擊圖標，來退出應用程序。大多數應用程序能夠通過右鍵單擊而退出，而一些應用程序（例如 Telegram 等），將被最小化到 <ruby>系統托盤<rt> system tray </rt></ruby> 中。</p><h4 id="使用鍵盤快捷鍵-以快速啓動程序塢中的應用程序-知道這個的人不多" tabindex="-1">使用鍵盤快捷鍵，以快速啓動程序塢中的應用程序 [知道這個的人不多] <a class="header-anchor" href="#使用鍵盤快捷鍵-以快速啓動程序塢中的應用程序-知道這個的人不多" aria-label="Permalink to “使用鍵盤快捷鍵，以快速啓動程序塢中的應用程序 [知道這個的人不多]”">​</a></h4><p>你只需用鼠標單擊程序塢上的圖標，即可啓動應用程序。但是，你也可以用鍵盤快捷鍵，來啓動應用程序。</p><p>使用 <code>WIN</code>/<code>Super</code> + <code>數字鍵</code> 的組合，能夠啓動程序塢中該位置的應用程序。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/01/keyboard-shortcut-for-ubuntu-dock.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>如果應用程序已經在運行了，它將被聚焦。</p><p>由於這個功能是基於位置的，所以請不要一直對圖標進行重新排序。就我個人而言，我把 Firefox 放在程序塢的第 1 個位置，文件管理器放在第 2 個位置，備用瀏覽器放在第 3 個位置，以此類推，直到第 9 個位置。這樣，我可以使用 <code>Super + 2</code>，從而快速啓動文件管理器。</p><p>因為我的系統連接了 3 個屏幕，所以我發現這個快速啓動應用程序的功能特別好用，我不必再將鼠標移動到第一個屏幕上的程序塢上了。你也可以在其他屏幕上啓用或禁用程序塢，我將在本教程的後面部分向你展示如何設置。</p><h3 id="改變程序塢在屏幕上的位置" tabindex="-1">改變程序塢在屏幕上的位置 <a class="header-anchor" href="#改變程序塢在屏幕上的位置" aria-label="Permalink to “改變程序塢在屏幕上的位置”">​</a></h3><p>默認情況下，程序塢位於屏幕的左側。但是，有些人喜歡將程序塢放置在屏幕底部。</p><p>Ubuntu 允許你更改程序塢的位置。你可以將程序塢移至底部或右側。我不覺得有很多人真的想要把擴展塢放在了頂部，所以沒有將擴展塢移到頂部的選項。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/01/change-launcher-position-ubuntu.png?resize=800%2C450&amp;ssl=1" alt="Change Launcher Position"></p><p>要更改程序塢位置，請進入 “<ruby>設置<rt> Settings </rt></ruby>” 菜單，然後點擊 “<ruby>外觀<rt> Appearance </rt></ruby>” ，你可以在 Dock 欄下看到一些選項，然後你可以在此處更改 “<ruby>屏幕上的位置<rt> Position on screen </rt></ruby>” 這一設置。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/01/change-dock-position-ubuntu.png?resize=800%2C450&amp;ssl=1" alt="Go to Settings-&gt;Appearance-&gt;Dock"></p><h4 id="程序塢在多顯示器設置中的位置" tabindex="-1">程序塢在多顯示器設置中的位置 <a class="header-anchor" href="#程序塢在多顯示器設置中的位置" aria-label="Permalink to “程序塢在多顯示器設置中的位置”">​</a></h4><p>如果你的系統連接了多個屏幕，你可以選擇是在所有的屏幕上還是在某個選定的屏幕上，顯示擴展塢。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/01/ubuntu-dock-settings-multimonitor.png?resize=800%2C450&amp;ssl=1" alt="Ubuntu Dock Settings Multimonitor"></p><p>對於我個人而言，我只在我的筆記本電腦屏幕上顯示程序塢，因為這是我的主屏幕。這樣在我的另外兩個屏幕會留有最大的空間。</p><h3 id="更改程序塢的外觀" tabindex="-1">更改程序塢的外觀 <a class="header-anchor" href="#更改程序塢的外觀" aria-label="Permalink to “更改程序塢的外觀”">​</a></h3><p>讓我們繼續看看 Ubuntu 程序塢中的更多自定義選項吧。</p><p>想像一下，如果你在程序塢中添加了太多的應用程序或打開了太多應用程序，那麼程序塢的空間會被填滿。如果你想要進入到程序塢端點處的應用程序，那麼你必須滾動到程序塢頂部和底部才可以。</p><p>你可以更改程序塢的圖標大小，來解決這個問題，這樣程序塢就能夠容納更多圖標來。不過，也不要讓圖標太小。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/01/normal-icon-size-dock.jpg?resize=1024%2C1080&amp;ssl=1" alt=""></p><p>要更改程序塢的圖標大小，請進入 “<ruby>設置<rt> Settings </rt></ruby>” 菜單，然後點擊 “<ruby>外觀<rt> Appearance </rt></ruby>” ，並通過移動 “<ruby>圖標大小<rt> Icon size </rt></ruby>” 下的滑塊來更改它。默認的圖標大小為 48 像素。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/01/changing-icon-size-in-ubuntu-dock.png?resize=800%2C450&amp;ssl=1" alt="Changing Icon Size In Ubuntu Dock"></p><h4 id="在程序塢中隱藏已安裝的磁盤圖標" tabindex="-1">在程序塢中隱藏已安裝的磁盤圖標 <a class="header-anchor" href="#在程序塢中隱藏已安裝的磁盤圖標" aria-label="Permalink to “在程序塢中隱藏已安裝的磁盤圖標”">​</a></h4><p>當你插入 U 盤或 SD 卡時，它的驅動器會安裝到系統中，並且在程序塢中會立即出現一個圖標。這個圖標很有用，因為你可以直接通過右鍵單擊它，來安全地刪除驅動器選項。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/01/external-mounted-disks-in-ubuntu-dock.png?resize=800%2C450&amp;ssl=1" alt="Mounted disks are displayed In the Ubuntu Dock"></p><p>如果你認為在程序塢中顯示已安裝的磁盤圖標很麻煩的話，你也可以關閉這個功能。別擔心，你仍然可以從文件管理器訪問已安裝的驅動器。</p><p>打開終端，使用以下命令，來隱藏程序塢中已安裝的磁盤圖標：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.shell.extensions.dash-to-dock show-mounts false</span></span></code></pre></div><p>更改會立即生效。你不再會為程序塢中顯示已安裝的磁盤而煩惱了。</p><p>如果你想要恢復默認情況，請使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.shell.extensions.dash-to-dock show-mounts true</span></span></code></pre></div><h3 id="改變程序塢的行為" tabindex="-1">改變程序塢的行為 <a class="header-anchor" href="#改變程序塢的行為" aria-label="Permalink to “改變程序塢的行為”">​</a></h3><p>接下來，讓我們自定義程序塢的默認行為，使它能更適合你的需求吧。</p><h4 id="啓用點擊最小化" tabindex="-1">啓用點擊最小化 <a class="header-anchor" href="#啓用點擊最小化" aria-label="Permalink to “啓用點擊最小化”">​</a></h4><p>如果你單擊一個正在運行的應用程序的圖標，那麼這個應用程序的窗口將成為焦點。當如果你<strong>再次單擊</strong>這個圖標時，將什麼都不會發生。這是因為，在默認情況下，第二次點擊同一圖標不會最小化應用程序。</p><p>這是現代桌面的默認行為，但我不太喜歡，我更喜歡的是：當我<strong>第二次點擊圖標時，應用程序會被最小化</strong>。</p>',65)),n("p",null,[t[1]||(t[1]=s("如果你像我一樣，那麼你可能想要在 Ubuntu 中 ",-1)),e(i,{href:"https://itsfoss.com/click-to-minimize-ubuntu/"},{default:o(()=>[...t[0]||(t[0]=[s("啓用點擊最小化選項",-1)])]),_:1}),t[2]||(t[2]=s("：",-1))]),t[30]||(t[30]=a('<p>為此，請打開終端並輸入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.shell.extensions.dash-to-dock click-action &#39;minimize&#39;</span></span></code></pre></div><h4 id="自動隱藏-ubuntu-程序塢-以獲得更多屏幕空間" tabindex="-1">自動隱藏 Ubuntu 程序塢，以獲得更多屏幕空間 <a class="header-anchor" href="#自動隱藏-ubuntu-程序塢-以獲得更多屏幕空間" aria-label="Permalink to “自動隱藏 Ubuntu 程序塢，以獲得更多屏幕空間”">​</a></h4><p>如果你想要有最大的屏幕空間，你可以在 Ubuntu 中為程序塢啓用自動隱藏選項。</p><p>自動隱藏選項會隱藏程序塢，你就能獲得整個屏幕。不過，程序塢仍然可以使用。將光標移動到程序塢原來所在的位置，它就會再次出現。當程序塢重新出現時，它會覆蓋在正在運行的應用程序窗口上。這是一件好事，否則太多元素會開始在屏幕上移動。</p><p>要設置程序塢自動隱藏，請進入 “<ruby>設置<rt> Settings </rt></ruby>” 菜單，然後點擊 “<ruby>外觀<rt> Appearance </rt></ruby>” ，你可以在 Dock 欄下開啓 <ruby>自動隱藏選項<rt> Auto-hide the Dock </rt></ruby>” 。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/01/autohide-dock-ubuntu.png?resize=800%2C450&amp;ssl=1" alt="Auto-hide the dock"></p><p>如果你不喜歡自動隱藏程序塢的話，你可以用同樣的方式禁用它。</p><h4 id="禁用-ubuntu-默認的程序塢" tabindex="-1">禁用 Ubuntu 默認的程序塢 <a class="header-anchor" href="#禁用-ubuntu-默認的程序塢" aria-label="Permalink to “禁用 Ubuntu 默認的程序塢”">​</a></h4><p>Ubuntu 程序塢的自動隱藏選項對很多人來説已經足夠好了，但是依舊有些用户根本不喜歡 Ubuntu 自帶的程序塢。如果你也是其中的一員，你可以選擇完全禁用 Ubuntu 的程序塢。</p>',10)),n("p",null,[t[4]||(t[4]=s("從 Ubuntu 20.04 開始，你可以使用 ",-1)),t[5]||(t[5]=n("ruby",null,[s("擴展應用程序"),n("rt",null," Extensions application ")],-1)),t[6]||(t[6]=s("，來管理 ",-1)),e(i,{href:"https://itsfoss.com/gnome-shell-extensions/"},{default:o(()=>[...t[3]||(t[3]=[s("GNOME 擴展",-1)])]),_:1}),t[7]||(t[7]=s("。",-1))]),t[31]||(t[31]=a('<p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/06/GNOME-extensions-app-ubuntu.jpg?resize=800%2C240&amp;ssl=1" alt="Look for Extensions app in the menu"></p><p>使用這個擴展應用程序，你就可以輕鬆地禁用或重新啓用程序塢了。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/01/disable-dock-ubuntu.png?resize=800%2C450&amp;ssl=1" alt="Disable Ubuntu Dock"></p><h3 id="使用-dconf-editor-進行高級的程序塢定製-不推薦" tabindex="-1">使用 dconf-editor 進行高級的程序塢定製 [不推薦] <a class="header-anchor" href="#使用-dconf-editor-進行高級的程序塢定製-不推薦" aria-label="Permalink to “使用 dconf-editor 進行高級的程序塢定製 [不推薦]”">​</a></h3><h5 id="請注意" tabindex="-1">請注意 <a class="header-anchor" href="#請注意" aria-label="Permalink to “請注意”">​</a></h5><p><code>dconf-editor</code> 能讓你更改 GNOME 桌面環境的幾乎每個方面。這個性質喜憂參半，因為你在更改時必須小心，而且大多數設置都可以即時更改，無需確認。雖然你可以重置你的更改，但你仍可能會將系統置於難以恢復正常的狀態。</p><p>出於這個原因，我不推薦你使用 <code>dconf-editor</code>，特別是如果你不喜歡花時間在故障排除和修復問題上，或者如果你不太熟悉 Linux 和 GNOME。</p>',7)),n("p",null,[e(i,{href:"https://wiki.gnome.org/Apps/DconfEditor"},{default:o(()=>[...t[8]||(t[8]=[s("dconf-editor",-1)])]),_:1}),t[9]||(t[9]=s(" 給你提供了在 Ubuntu 中自定義程序塢的其他選項。你可以在從軟件中心安裝 ",-1)),t[10]||(t[10]=n("code",null,"dconf-editor",-1)),t[11]||(t[11]=s("，然後導航到 ",-1)),t[12]||(t[12]=n("code",null,"org > gnome > shell > extensions > dash-to-dock",-1)),t[13]||(t[13]=s("，在這裏你會找到很多自定義程序塢的選擇。",-1))]),t[32]||(t[32]=a('<p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/01/dconf-editor-dock.png?resize=592%2C599&amp;ssl=1" alt=""></p><h3 id="替換-ubuntu-默認的程序塢" tabindex="-1">替換 Ubuntu 默認的程序塢 <a class="header-anchor" href="#替換-ubuntu-默認的程序塢" aria-label="Permalink to “替換 Ubuntu 默認的程序塢”">​</a></h3><p>有幾個第三方的程序塢應用程序可用於 Ubuntu 和其他 Linux 發行版。你可以安裝你想要的第三方程序塢，並使用它。</p><p>例如，你可以從軟件中心下載 “Plank dock”，並以與 Ubuntu 程序塢類似的方式來使用它。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/01/plank-dock-Ubuntu.jpg?resize=800%2C382&amp;ssl=1" alt="Plank Dock in Ubuntu"></p><p>在這種情況下，禁用 Ubuntu 默認的程序塢會是一個更好的主意，因為同時使用多個擴展塢是不太明智的。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>本教程介紹了在 GNOME 實現中，如何自定義 Ubuntu 默認的程序塢。上述程序塢的更改在 vanilla GNOME 的程序塢上運行良好。</p><p>我已經向你展示了大多數常見的 Ubuntu 程序塢的定製方法。你不需要去盲目地跟隨教程中的所有步驟。閲讀並思考哪一個是你需要的，然後根據教程中的方法更改配置。</p><p>如果你不喜歡 Ubuntu 默認的程序塢，也有其他的程序塢可供試驗。</p><p>這個教程讓你學到了新東西嗎？你還想看到更多這樣的教程嗎？歡迎你在評論區中建議和反饋。</p><hr>',12)),n("p",null,[t[15]||(t[15]=s("via: ",-1)),e(i,{href:"https://itsfoss.com/customize-ubuntu-dock/"},{default:o(()=>[...t[14]||(t[14]=[s("https://itsfoss.com/customize-ubuntu-dock/",-1)])]),_:1})]),n("p",null,[t[20]||(t[20]=s("作者：",-1)),e(i,{href:"https://itsfoss.com/author/abhishek/"},{default:o(()=>[...t[16]||(t[16]=[s("Abhishek Prakash",-1)])]),_:1}),t[21]||(t[21]=s(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[17]||(t[17]=[s("lujun9972",-1)])]),_:1}),t[22]||(t[22]=s(" 譯者：",-1)),e(i,{href:"https://github.com/chai001125"},{default:o(()=>[...t[18]||(t[18]=[s("chai001125",-1)])]),_:1}),t[23]||(t[23]=s(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:o(()=>[...t[19]||(t[19]=[s("wxy",-1)])]),_:1})]),n("p",null,[t[26]||(t[26]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[24]||(t[24]=[s("LCTT",-1)])]),_:1}),t[27]||(t[27]=s(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:o(()=>[...t[25]||(t[25]=[s("Linux中國",-1)])]),_:1}),t[28]||(t[28]=s(" 榮譽推出",-1))])])}const U=p(d,[["render",b]]);export{C as __pageData,U as default};
